    if last_action is not None:
        if last_action == 0:  # turn_left executed
            memory['dir'] = (memory['dir'] - 1) % 4
        elif last_action == 1:  # turn_right executed
            memory['dir'] = (memory['dir'] + 1) % 4
        elif last_action == 2:
            # forward executed: we moved one cell in the facing direction (if move succeeded)
            # We cannot track absolute position, but it's progress -> reset progress counters
            memory['no_progress'] = 0
            memory['steps_since_move'] = 0
        elif last_action in (3, 5):  # pickup or toggle may change visible state
            memory['no_progress'] = 0
            memory['steps_since_move'] = 0
