    # returns 0 (turn_left) or 1 (turn_right) to make progress
    def rotation_toward(desired_dir):
        cur = memory['dir']
        # compute shortest rotation (left or right)
        diff = (desired_dir - cur) % 4
        if diff == 0:
            return None
        if diff == 1:
            return 1
        if diff == 3:
            return 0
        # diff == 2: both ways equal; use turn_pref
        return 1 if memory['turn_pref'] == 1 else 0

