                if o == 8:
                    return 2
                # Otherwise, attempt to move forward if allowed
                if can_forward():
                    return 2
                # Forward not allowed (wall or closed door) -> rotate instead
                return 1 if memory['turn_pref'] == 1 else 0
            else:
                # Target not the immediate front cell: prefer moving forward if that decreases distance
                if can_forward():
                    return 2
                # Forward blocked: rotate to try alternate path
                return 1 if memory['turn_pref'] == 1 else 0
        else:
            # Need to rotate toward desired_dir
            rot = rotation_toward(desired_dir)
            if rot is not None:
                return rot
            # fallback
            return 1

    # Generic function to move toward a visible object (key/door/goal)
    def move_toward_visible(obj_type):
        items = find_all(obj_type)
