            # rotate to explore; prefer turn_pref but occasionally try the other
            if memory['steps_since_move'] > 6:
                # flip once to escape potential loop
                memory['turn_pref'] = 1 - memory['turn_pref']
                memory['steps_since_move'] = 0
            return 1 if memory['turn_pref'] == 1 else 0

    # Phase 3: carrying key, go to door and unlock
    if memory['phase'] == 3:
        doors = find_all(4)
