import random
from collections import deque

def controller(obs, memory) -> int:
    # ACTIONS: 0 turn_left, 1 turn_right, 2 forward, 3 pickup, 4 drop, 5 toggle, 6 done
    img = obs['image']
    last_action = obs.get('last_action', None)

    AG_X, AG_Y = 3, 6  # agent's egocentric coordinates (fixed in the view)

    # Initialize memory
    memory.setdefault('phase', 1)       # 1: seek key, 3: open door, 4: go to goal
    memory.setdefault('view_history', deque(maxlen=16))
    memory.setdefault('stuck_steps', 0)
    memory.setdefault('turn_pref', 1)   # 1 prefer right, 0 prefer left
    memory.setdefault('rand_seed', 0)

    # Small RNG deterministic-ish per episode
    memory['rand_seed'] = (memory['rand_seed'] * 97 + 13) % 1000003
    rnd = random.Random(memory['rand_seed'])

    # Helpers to access cells
    def cell(x, y):
        if 0 <= x < 7 and 0 <= y < 7:
            return img[x][y]
        return (0, 0, 0)  # unseen/out of bounds

    def front_cell():
        return cell(AG_X, AG_Y - 1)

    def rel_cell(rel):  # relative cell index: 0=front,1=right,2=left,3=back (back may be OOB)
        if rel == 0:
            return front_cell(), (AG_X, AG_Y - 1)
        if rel == 1:  # right: (x+1, y) relative in current egocentric view
            return cell(AG_X + 1, AG_Y), (AG_X + 1, AG_Y)
        if rel == 2:  # left: (x-1, y)
            return cell(AG_X - 1, AG_Y), (AG_X - 1, AG_Y)
        if rel == 3:  # back (rare)
            return cell(AG_X, AG_Y + 1), (AG_X, AG_Y + 1)
        return ((0,0,0), (0,0))

    def is_traversable_obj(o, s):
        # allowed target objects for forward move into that cell
        # treat empty (1) and floor (3), goal (8) and open door (4 with state 0) as traversable
        if o in (1, 3, 8):
            return True
        if o == 4 and s == 0:
            return True
        return False

    def rel_traversable(rel):
        (o, c, s), (x, y) = rel_cell(rel)
        if o == 0:
            return False
        return is_traversable_obj(o, s)

    def visible_cells_hash():
        # create a hash of visible non-zero cells (ignore unseen zeros) to detect view changes
        vals = []
        for x in range(7):
            for y in range(7):
                o, c, s = img[x][y]
                if o != 0:
                    vals.append((x, y, o, c, s))
        return tuple(vals)

    def find_all(obj_type):
        res = []
        for x in range(7):
            for y in range(7):
                o, c, s = img[x][y]
                if o == obj_type:
                    res.append((x, y, c, s))
        return res

    def manhattan(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    # Update view history and stuck detection
    vh = visible_cells_hash()
    if not memory['view_history'] or memory['view_history'][-1] != vh:
        memory['view_history'].append(vh)
        memory['stuck_steps'] = 0
    else:
        memory['stuck_steps'] += 1

    # Determine carried object from image[3][6]
    carried_obj, carried_col, carried_state = img[3][6]
    carrying_key = (carried_obj == 5)

    # Phase decision (robust, recompute every step)
    if not carrying_key:
        memory['phase'] = 1
    else:
        # if an open door or the goal visible, go to goal; else open door
        doors = find_all(4)
        door_open_visible = any(d[3] == 0 for d in doors)
        if door_open_visible:
            memory['phase'] = 4
        else:
            memory['phase'] = 3

    # Action utilities
    def safe_pickup():
        o, c, s = front_cell()
        if o == 5:
            return 3
        return None

    def safe_toggle():
        o, c, s = front_cell()
        if o == 4:
            return 5
        return None

    # Move toward a visible object using image coords (does not rely on an internal orientation estimate)
    def move_toward_visible(obj_type):
        items = find_all(obj_type)
        if not items:
            return None
        # pick nearest in Manhattan distance
        best = min(items, key=lambda it: manhattan((AG_X, AG_Y), (it[0], it[1])))
        tx, ty, col, st = best
        dx = tx - AG_X
        dy = ty - AG_Y
        # If target is in front cell
        if dx == 0 and dy == -1:
            # front: pickup if key, toggle if door, forward if goal or open
            o, c, s = front_cell()
            if obj_type == 5 and o == 5:
                return 3
            if obj_type == 4 and o == 4:
                return 5
            if obj_type == 8 and o == 8:
                return 2
            # otherwise, if forward is traversable, go forward
            if is_traversable_obj(o, s):
                return 2
            # blocked: try to rotate to find a way
            return 1 if memory['turn_pref'] == 1 else 0
        # Prefer reducing larger absolute difference
        if abs(dx) >= abs(dy):
            # horizontal move desired
            if dx > 0:
                # try to go right: check cell (4,6)
                o, c, s = cell(AG_X + 1, AG_Y)
                if o != 0 and is_traversable_obj(o, s):
                    # to go right, turn right now (the executor will handle move next step)
                    return 1
                # if front is traversable, go front
                of, cf, sf = front_cell()
                if of != 0 and is_traversable_obj(of, sf):
                    return 2
                # else try left
                ol, cl, sl = cell(AG_X - 1, AG_Y)
                if ol != 0 and is_traversable_obj(ol, sl):
                    return 0
                # else rotate to explore
                return 1 if memory['turn_pref'] == 1 else 0
            else:
                # dx < 0 -> go left
                o, c, s = cell(AG_X - 1, AG_Y)
                if o != 0 and is_traversable_obj(o, s):
                    return 0
                of, cf, sf = front_cell()
                if of != 0 and is_traversable_obj(of, sf):
                    return 2
                oR, cR, sR = cell(AG_X + 1, AG_Y)
                if oR != 0 and is_traversable_obj(oR, sR):
                    return 1
                return 0 if memory['turn_pref'] == 0 else 1
        else:
            # vertical move desired (dy is negative for front)
            if dy < 0:
                # move forward toward target
                of, cf, sf = front_cell()
                if of != 0 and is_traversable_obj(of, sf):
                    return 2
                # else try to rotate to find path
                return 1 if memory['turn_pref'] == 1 else 0
            else:
                # target is behind us (rare); try to go lateral instead
                oR, cR, sR = cell(AG_X + 1, AG_Y)
                if oR != 0 and is_traversable_obj(oR, sR):
                    return 1
                oL, cL, sL = cell(AG_X - 1, AG_Y)
                if oL != 0 and is_traversable_obj(oL, sL):
                    return 0
                # fallback rotate
                return 1 if memory['turn_pref'] == 1 else 0

    # Exploration fallback: a right-hand-rule style to avoid getting stuck (uses only relative cells)
    def explore_step():
        # prefer right -> front -> left -> turn around
        if rel_traversable(1):
            # turn right now (and hopefully forward next)
            return 1
        if rel_traversable(0):
            return 2
        if rel_traversable(2):
            return 0
        # none traversable: try rotating to find visibility (prefer turn_pref)
        if memory['stuck_steps'] > 8:
            # after being stuck, try the other turn to escape loops
            memory['turn_pref'] = 1 - memory['turn_pref']
            # perform that rotation
            return 1 if memory['turn_pref'] == 1 else 0
        return 1 if memory['turn_pref'] == 1 else 0

    # Phase behaviors
    # Phase 1: seek key
    if memory['phase'] == 1:
        keys = find_all(5)
        if keys:
            action = move_toward_visible(5)
            if action is not None:
                # safety: only pickup if front is actually a key
                if action == 3:
                    of, cf, sf = front_cell()
                    if of != 5:
                        # avoid useless pickup
                        return explore_step()
                return action
        # Key not visible: explore
        return explore_step()

    # Phase 3: carrying key, open door (unlock)
    if memory['phase'] == 3:
        doors = find_all(4)
        if doors:
            # prefer the nearest door
            best = min(doors, key=lambda d: manhattan((AG_X, AG_Y), (d[0], d[1])))
            tx, ty, dcol, dstate = best
            dx = tx - AG_X
            dy = ty - AG_Y
            # If door is directly front, toggle it
            if dx == 0 and dy == -1:
                of, cf, sf = front_cell()
                if of == 4:
                    return 5
                # else if front traversable just go forward
                if of != 0 and is_traversable_obj(of, sf):
                    return 2
                return explore_step()
            # otherwise move toward it like move_toward_visible
            action = move_toward_visible(4)
            if action is not None:
                return action
        # door not visible: explore to find it
        return explore_step()

    # Phase 4: go to goal / go through open door
    if memory['phase'] == 4:
        goals = find_all(8)
        if goals:
            action = move_toward_visible(8)
            if action is not None:
                # ensure we use forward rather than pickup (just in case)
                if action == 3:
                    return 2
                return action
        # If an open door is immediately front, go through
        of, cf, sf = front_cell()
        if of == 4 and sf == 0:
            if is_traversable_obj(of, sf):
                return 2
            else:
                return explore_step()
        return explore_step()

    # Fallback (shouldn't be reached)
    return explore_step()
